import{z as s,x as i,o as r,c as d,q as t,j as n,D as A,d as B,s as l,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"失败实验的归档","description":"","frontmatter":{"title":"失败实验的归档","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-failed-exp-archive.md","filePath":"llm/ti-failed-exp-archive.md","lastUpdated":1791063341000}'),p={name:"llm/ti-failed-exp-archive.md"};function D(u,E,m,C,h,F){const e=i("Mermaid");return r(),d("div",null,[E[2]||(E[2]=t('<h1 id="失败实验的归档" tabindex="-1">失败实验的归档 <a class="header-anchor" href="#失败实验的归档" aria-label="Permalink to &quot;失败实验的归档&quot;">​</a></h1><div class="epigraph"><p>被归档的失败是资产，被遗忘的失败是按时复利的负债：没有死亡档案的团队，会反复为同一个死法付学费。</p><footer>—— 据 OPT 训练日志与大规模预训练团队复盘实践整理</footer></div><p><a href="/llm/ti-multiexp-scheduling">上一课</a>把卡分给各个实验，而实验的一部分注定失败：发散、平台、被更好的想法取代。失败的去向是本课的主题。跟踪系统保证查得到每次 run 的曲线与判词，但「查得到」不等于「读得懂」：死因散落在聊天记录里，曲线快照随目录清理消失。本课写失败实验的归档制度。量化栏的<a href="/quant/research-postmortem">复盘与案例写作</a>为策略失败定了同构的规矩，本课把它落到训练场景。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不归档的失败以三种方式反弹。<strong>重跑</strong>：半年后有人提出「试试更大的 dropout」，没人记得这方向试过三次、死在哪一步——当时的结论从未写成可检索的字段。<strong>误归因</strong>：死掉的 run 只留下「效果不好」一句评价，而这不是死因；下次遇到相似症状，团队在错误的假说上再烧一轮卡。<strong>幸存者偏差</strong>：只复盘成功，方法论从成功案例里归纳，而成功常含运气；失败才暴露机制的边界。归档的对象因此不只是「死掉的 run」，还有每一次「为什么停」的判断本身。</p><p><span class="marginnote">常见误区：初学者容易把「效果不好」当死因写进档案，实际上这只描述了结果、没定位机制——发散死在数值稳定性，平台死在数据或容量，两者的下一步动作完全不同。死因必须落到判据与证据上，下次遇到相似症状才能一步查档，而不是再猜一轮。</span></p><h3 id="死因分类学" tabindex="-1">死因分类学 <a class="header-anchor" href="#死因分类学" aria-label="Permalink to &quot;死因分类学&quot;">​</a></h3><p>死因必须落在<strong>判据</strong>上，判据就是判读课启动时写下的死线。最小分类五类：发散（触发散线，附尖峰区间与分因结论）、平台（触平台线，附外推证据）、资源（预算耗尽或被抢占，附进度）、被取代（同方向的更优 run 存在，附指针）、事故（基础设施故障不可恢复，附事故链接）。每条死因必须带<strong>证据指针</strong>：曲线冻结快照、评测表、当时的绊网日志。「感觉不好」不允许作为死因入库。</p><p><span class="marginnote">曲线快照在杀 run 当刻冻结：原始序列、双档 EMA、分期与尖峰标注一并定稿。事后补画的曲线会被后续知识污染——归档的是「当时知道什么」，不是「现在怎么看当时」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>归档流程三个动作，在杀 run 的当下完成，不做「以后补」。<strong>冻结</strong>：曲线快照、配置哈希、数据指纹、检查点指针锁定成不可变记录，挂进跟踪库该 run 的条目。<strong>判死</strong>：按五分类填死因与证据指针，判据引用启动时的死线原文——触线就是触线，不因投入了多少卡而改判。<strong>提炼</strong>：一句话写「这次失败排除了什么、下次该改什么」，并打上方向标签（配比、稳定、容量、流程）。提炼是唯一需要判断力的步骤，也最常被跳过：没有提炼的档案是坟场，有提炼的档案是地图。</p><p>组织动作两条：新人入职先读十份历史死因档案；月度扫一次死因分布，占比上升说明某层防线在漏水——「事故」类上升指向基础设施，「发散」类上升指向数值或数据。</p>',12)),(r(),n(o,null,{default:A(()=>[l(e,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E8%A7%A6%E6%AD%BB%E7%BA%BF%3A%20%E6%9D%80%20run%22%5D%20--%3E%20FZ%5B%22%E5%86%BB%E7%BB%93%3A%20%E6%9B%B2%E7%BA%BF%E5%BF%AB%E7%85%A7%20%2B%20%E9%85%8D%E7%BD%AE%20%2B%20%E6%8C%87%E9%92%88%22%5D%0A%20%20FZ%20--%3E%20DC%7B%22%E6%AD%BB%E5%9B%A0%E4%BA%94%E5%88%86%E7%B1%BB%22%7D%0A%20%20DC%20--%3E%20E%5B%22%E9%99%84%E8%AF%81%E6%8D%AE%3A%20%E5%B0%96%E5%B3%B0%E5%8C%BA%E9%97%B4%20%2F%20%E5%A4%96%E6%8E%A8%20%2F%20%E4%BA%8B%E6%95%85%E9%93%BE%E6%8E%A5%22%5D%0A%20%20E%20--%3E%20LS%5B%22%E6%8F%90%E7%82%BC%E4%B8%80%E5%8F%A5%3A%20%E6%8E%92%E9%99%A4%E4%BA%86%E4%BB%80%E4%B9%88%2C%20%E4%B8%8B%E6%AC%A1%E6%94%B9%E4%BB%80%E4%B9%88%22%5D%0A%20%20LS%20--%3E%20TAG%5B%22%E6%89%93%E6%96%B9%E5%90%91%E6%A0%87%E7%AD%BE%E5%85%A5%E5%BA%93%22%5D%0A%20%20TAG%20--%3E%20Q%5B%22%E6%A3%80%E7%B4%A2%3A%20%E6%8C%89%E6%AD%BB%E5%9B%A0%20%2F%20%E6%96%B9%E5%90%91%20%2F%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20Q%20--%3E%20REVIEW%5B%22%E6%9C%88%E5%BA%A6%E6%AD%BB%E5%9B%A0%E5%88%86%E5%B8%83%E6%89%AB%E6%8F%8F%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("归档有效的机理是"),a("strong",null,"把负结果变成可检索状态"),B("：试过什么方向的查询成本降到一次检索，重复学费才真正停付；五分类让死因可统计，统计才暴露系统性弱点。冻结快照的机理与证据保全相同：归档的价值在「当时的完整上下文」，任何事后可变的字段都会让档案失去作证资格。提炼的机理是压缩：档案读的是结论与指针，不是全量曲线；一句话排除法把整场 run 的信息压进可传递的尺寸。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：只复盘成功就像只研究中奖彩票的号码规律——中奖常含运气，规律不可迁移；失败却稳定暴露机制的边界。航空业的安全记录正是靠把每次事故写成可检索档案换来的，而不是靠研究顺利航班。")],-1)),E[6]||(E[6]=a("p",null,"免责文化是制度的隐形前提：归档若被用作追责证据，下次的死因栏会集体写成「资源不足」。复盘免责、案例同权，与死因落在判据上是同一套纪律的两面。",-1)),(r(),n(o,null,{default:A(()=>[l(e,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%9C%88%E5%BA%A6%E6%AD%BB%E5%9B%A0%E5%88%86%E5%B8%83%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20C%7B%22%E5%93%AA%E7%B1%BB%E5%8D%A0%E6%AF%94%E5%9C%A8%E4%B8%8A%E5%8D%87%3F%22%7D%0A%20%20C%20--%3E%7C%22%E4%BA%8B%E6%95%85%22%7C%20A%5B%22%E5%9F%BA%E7%A1%80%E8%AE%BE%E6%96%BD%E9%98%B2%E7%BA%BF%E6%BC%8F%E6%B0%B4%3A%20%E4%BF%AE%E8%B0%83%E5%BA%A6%E4%B8%8E%E5%AE%B9%E9%94%99%22%5D%0A%20%20C%20--%3E%7C%22%E5%8F%91%E6%95%A3%22%7C%20N%5B%22%E6%95%B0%E5%80%BC%E6%88%96%E6%95%B0%E6%8D%AE%E9%98%B2%E7%BA%BF%E6%BC%8F%E6%B0%B4%3A%20%E6%9F%A5%E5%88%9D%E5%A7%8B%E5%8C%96%E4%B8%8E%E9%85%8D%E6%AF%94%22%5D%0A%20%20C%20--%3E%7C%22%E5%B9%B3%E5%8F%B0%22%7C%20S%5B%22%E5%AE%B9%E9%87%8F%E6%88%96%E6%95%B0%E6%8D%AE%E8%A7%81%E9%A1%B6%3A%20%E6%9F%A5%E5%A4%96%E6%8E%A8%E8%AF%81%E6%8D%AE%22%5D%0A%20%20C%20--%3E%7C%22%E8%B5%84%E6%BA%90%22%7C%20B%5B%22%E9%A2%84%E7%AE%97%E4%B8%8E%E4%BC%98%E5%85%88%E7%BA%A7%E5%A4%B1%E9%85%8D%3A%20%E6%9F%A5%E7%AB%8B%E9%A1%B9%E5%8F%A3%E5%BE%84%22%5D%0A%20%20C%20--%3E%7C%22%E8%A2%AB%E5%8F%96%E4%BB%A3%22%7C%20D%5B%22%E6%96%B9%E5%90%91%E6%AD%A3%E5%B8%B8%E6%94%B6%E6%95%9B%2C%20%E9%9D%9E%E6%BC%8F%E6%B0%B4%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">为什么重要：如果归档被拿去追责，下次所有人都会把死因写成「资源不足」这种最安全的假话，整套档案立刻失真。复盘免责不是宽容，是保证数据为真的前提——假档案比没有档案更贵，因为它会以「有据可查」的样子误导后来的检索者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>归档管失败的<strong>记录与复用</strong>，不管失败的技术成因：发散为什么发生、平台意味着什么，归判读与数值各课；也不管被杀 run 的资源回收——那在调度课的退出流程里。五分类之外的长尾（例如「保密原因停跑」）允许自由文本，但要单独标注而不混入统计。档案也有寿命：基础设施换代后，「事故」类死因的细节不再可迁移，按方向标签保留结论、按时间归档细节即可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不归档的失败按时复利：重跑、误归因、幸存者偏差三种反弹。</li><li>死因五分类：发散、平台、资源、被取代、事故；必须落在判据上并附证据指针。</li><li>杀 run 当刻完成冻结、判死、提炼，提炼一句写明排除了什么。</li><li>曲线快照定稿不可变，归档的是「当时知道什么」。</li><li>出处：据 OPT 训练日志（Zhang et al., 2022）与大规模训练复盘实践整理；同构纪律见量化栏<a href="/quant/research-postmortem">复盘与案例写作</a>。</li></ul>',5))])}const c=s(p,[["render",D]]);export{f as __pageData,c as default};
